    Exemplo de forward_static_call_array


<?php

class A
{
    const NAME = 'A';
    public static function test() {
        $args = func_get_args();
        echo static::NAME, " ".join(',', $args)." \n";
    }
}

class B extends A
{
    const NAME = 'B';

    public static function test() {
        echo self::NAME, "\n";
        forward_static_call_array(array('A', 'test'), array('mais', 'argumentos'));
        forward_static_call_array( 'test', array('outros', 'argumentos'));
    }
}

B::test('foo');

function test() {
        $args = func_get_args();
        echo "C ".join(',', $args)." \n";
    }

?>


    &example.outputs;


B
B mais,argumentos
C outros,argumentos
